def transform(grid):
    # Identify grid spacing from uniform separator rows/columns; encode each
    # lattice cell by the color at its separator intersections.
    h,w=len(grid),len(grid[0])
    rows=[]
    for r,row in enumerate(grid):
        if len(set(row))<=2 and (not rows or r-rows[-1]>1): rows.append(r)
    cols=[]
    for c in range(w):
        vals={grid[r][c] for r in range(h)}
        if len(vals)<=2 and (not cols or c-cols[-1]>1): cols.append(c)
    # color at each crossing is the pixel of the reduced output
    return [[grid[r][c] for c in cols] for r in rows]
